"""Accessible public benchmark sections, backed by the generated data snapshot."""
from html import escape as h
import json,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

def data():return json.loads((ROOT/'web/benchmarks/benchmark-data.json').read_text(encoding='utf-8'))

def publish_assets(output):
    target=output/'assets/benchmarks';target.mkdir(parents=True,exist_ok=True)
    for p in (ROOT/'web/benchmarks').iterdir():
        if p.is_file():shutil.copyfile(p,target/p.name)

def benchmark_home():
    d=data();vs=next(r for r in d['totals'] if r['host']=='vscode' and r['profile']=='gncore-after');ag=next(r for r in d['totals'] if r['host']=='antigravity' and r['profile']=='gncore-after')
    return f'''<section class="benchmark-home" aria-labelledby="benchmark-heading"><div class="container">
    <div class="benchmark-kicker">BENCHMARKS / OPEN MEASUREMENTS</div><div class="section-heading"><h2 id="benchmark-heading">Measured work.<br><em>Visible evidence.</em></h2><a class="btn btn-dark" href="/benchmarks/">Explore the benchmarks ↗</a></div>
    <p class="benchmark-lead">Real task checks, saved outputs, and a clear view of what each result means.</p>
    <p class="benchmark-kicker">HISTORICAL IDE PILOT · 29 OCT 2026 · ONE TRIAL PER CONDITION · 29 NON-UI CATEGORIES</p>
    <div class="benchmark-stat-row"><div><strong>{vs['percent']:.1f}<span>%</span></strong><p>VS Code revised pilot</p><small>{vs['passed']}/{vs['total']} reviewed checks</small></div><div><strong>{ag['percent']:.1f}<span>%</span></strong><p>Antigravity revised pilot</p><small>{ag['passed']}/{ag['total']} reviewed checks</small></div><div><strong>29<span>/30</span></strong><p>Categories fully reviewed</p><small>UI measurements remain open</small></div></div>
    <figure class="benchmark-figure"><img src="/assets/benchmarks/ide-pilot.svg" width="1280" height="720" loading="lazy" alt="Historical IDE pilot: VS Code baseline 164/173, references 158/173, revised 168/173; Antigravity baseline 140/173, references 132/173, revised 147/173."><figcaption>Historical pilot · 29 October 2026 · Same holdout tasks · Single unblinded trial. These are prior trial results, not current-release accuracy or a ranking of AI companies.</figcaption></figure>
    <div class="benchmark-links"><a href="/benchmarks/#methodology">Read the methodology ↗</a><a href="/assets/benchmarks/benchmark-data.json" download>Download the source data ↓</a><a href="/assets/benchmarks/GNCore-benchmark-report.pdf">Open the landscape report ↗</a></div>
    </div></section>'''

CHARTS=[
 ('ide-pilot','historical','Same tasks. Separate IDEs.','The baseline, published references and revised GNCore trial answered the same holdout tasks within each IDE. Scores count applicable manually reviewed criteria across 29 non-UI categories.','Historical pilot; one unblinded trial. The trial guides predate the current release. Model and host effects cannot be isolated.'),
 ('all-categories','historical','Every developer category.','See passed checks, denominators and percentages for all 30 categories in each condition. Gray cells retain measurements that are still open.','A small task sample cannot establish a domain-wide success probability. Open the SVG to zoom, or use the accessible table below.'),
 ('code-checks','historical','Generated code, exercised.','Allocation, numerical loss and gradients, and mutation-testing fixtures were executed on saved pilot implementations. Several conditions tied on these checks.','The revised VS Code allocation passed 16 frozen cases but failed 3 later exploratory cases. Separate follow-up repairs passed those cases; the historical chart remains unchanged.'),
 ('security-fixture','historical','Security findings, with safe controls.','All three conditions in both IDEs identified six seeded findings and flagged none of four safe controls in a manual fixture review.','This was a bounded manual fixture, with no exploits executed. It is not a production security certification or a broad security score.'),
 ('routing-corpus','local','A clear view of routing.','Normal authored prompts matched their category in 18 of 30 cases. Requests for more context are shown separately for normal, underspecified and boundary prompts.','This diagnostic corpus was authored with the library. It is not held out. Explicit skill selection is available when a project needs a specific category.'),
 ('entrypoint-footprint','local','Smaller entry instructions, full resources.','The curves show the distribution of entrypoint file sizes across all 30 categories before and after the instruction restructuring. Detailed procedures stay in linked resources.','These are UTF-8 bytes, not token counts. No inference speed, cost saving or output-quality gain is inferred from file size.'),
 ('local-latency','local','Local operations, timed.','Rendering a guide, explicit routing and resource reads are measured separately. The horizontal axis is logarithmic; the curves show how many recorded samples finished by each time.','Warm in-process CPU and filesystem measurements on one machine. This excludes IDE latency, model reasoning, network requests and real application runtime.')]

def benchmark_page():
    d=data();cards=[]
    for slug,group,title,text,limit in CHARTS:
        cards.append(f'''<section class="benchmark-panel" data-benchmark-group="{group}" id="{slug}" aria-labelledby="{slug}-heading"><div class="benchmark-panel-head"><span class="benchmark-kicker">{'HISTORICAL IDE PILOT' if group=='historical' else 'LOCAL MEASUREMENT'}</span><h2 id="{slug}-heading">{h(title)}</h2><p>{h(text)}</p></div><figure><a class="benchmark-zoom" href="/assets/benchmarks/{slug}.svg" aria-label="Open {h(title)} chart at full size"><img class="benchmark-chart" src="/assets/benchmarks/{slug}.svg" loading="lazy" alt="{h(title)} {h(text)}"></a><figcaption>{h(limit)}</figcaption></figure><div class="benchmark-links"><a href="/assets/benchmarks/{slug}.svg">Zoom SVG ↗</a><a href="/assets/benchmarks/{slug}.pdf" download>Download chart PDF ↓</a></div></section>''')
    hosts=['vscode','antigravity'];profiles=['gncore-before','reference','gncore-after'];rows=[]
    for cat in sorted({r['category'] for r in d['categories']}):
        cells=[]
        for host in hosts:
            for profile in profiles:
                r=next(r for r in d['categories'] if r['category']==cat and r['host']==host and r['profile']==profile)
                cells.append(f"<td>{r['passed']}/{r['total']} · {r['percent']:.1f}%</td>" if r['complete'] else '<td>Unmeasured</td>')
        rows.append(f'<tr><th scope="row">{h(cat)}</th>'+''.join(cells)+'</tr>')
    table='<details class="benchmark-table"><summary>Read the complete 30-category results table</summary><div class="table-scroll"><table class="data-table"><caption>Historical holdout review: passed/applicable criteria. One task per category and condition.</caption><thead><tr><th scope="col">Category</th>'+''.join(f'<th scope="col">{host}<br>{p}</th>' for host in ['VS Code','Antigravity'] for p in ['Baseline','Reference','Revised'])+'</tr></thead><tbody>'+''.join(rows)+'</tbody></table></div></details>'
    stats=d['catalog'];tests=d.get('package_tests');tests_text=f"{tests['passed']} passed, {tests.get('failed',0)} failed, {tests['skipped']} skipped in the recorded local package suite." if tests else 'The release verification record records package test outcomes separately from AI evaluation.'
    return '''<section class="container page-intro benchmark-intro"><span class="eyebrow">BENCHMARKS / THE EVIDENCE LIBRARY</span><h1>Every result.<br><em>With its context.</em></h1><p>A closer look at GNCore’s measured work: historical IDE trials, executed fixtures, local operations and the boundaries of each result.</p><div class="benchmark-links"><a href="#methodology">Methodology ↓</a><a href="/assets/benchmarks/GNCore-benchmark-report.pdf">Complete chart report ↗</a><a href="/assets/benchmarks/benchmark-data.json" download>Data JSON ↓</a><a href="/assets/benchmarks/category-results.csv" download>Category CSV ↓</a></div></section>
    <div class="container benchmark-toolbar" role="group" aria-label="Filter benchmark figures"><button type="button" data-benchmark-filter="all" aria-pressed="true">All evidence</button><button type="button" data-benchmark-filter="historical" aria-pressed="false">IDE pilot</button><button type="button" data-benchmark-filter="local" aria-pressed="false">Local measurements</button><span id="benchmark-filter-status" role="status" aria-live="polite">7 figures</span></div><div class="container benchmark-panels">'''+''.join(cards)+table+f'''<section class="benchmark-methodology" id="methodology"><span class="benchmark-kicker">METHOD / SOURCES / LIMITS</span><h2>What the numbers mean.</h2><div class="method-grid"><article><h3>One check is one criterion.</h3><p>168/173 means 168 applicable review criteria passed. Criteria are pooled across 29 fully reviewed non-UI categories; categories have slightly different denominators. Every category’s count is available in the table.</p></article><article><h3>Compare within an IDE.</h3><p>The historical comparison uses the same tasks in each condition. Manual review was unblinded; Copilot Auto was not fixed to one model. There is one task per category and no repeated-trial estimate or no-skill control.</p></article><article><h3>Keep trials separate.</h3><p>The historical pilot predates the current release. Known-task repairs and withdrawn development quality scores are excluded. An incomplete later fresh-context comparison provides no balanced quality ranking.</p></article><article><h3>Inspect the source.</h3><p>Thirty reference guides were pinned across fourteen repositories, including Anthropic, Vercel, Supabase and specialist projects. Each task uses its relevant reference; these are not aggregate scores for those companies.</p></article></div><h3>Current catalog and package</h3><p>{stats['categories']} categories, {stats['workflows']} workflows and {stats['resources']:,} declared resources. {h(tests_text)} Resource hashes and package tests verify files and software behavior; they do not certify arbitrary AI output.</p><p>Public version: {h(d['current_version'])}. Local timing snapshot: {h(d['local_recorded_at_utc'])}. The router diagnostic is in-corpus, with 18/30 normal prompts matching their authored category. GPU training, hardware behavior, deployed applications and full accessibility are not measured by these plots.</p><div class="benchmark-links"><a href="https://github.com/paladuguganeshnaidu/gncore/tree/main/web-results/comparison">Raw historical IDE evidence ↗</a><a href="https://github.com/paladuguganeshnaidu/gncore/tree/main/web-results/improvement-cycle-1">Revision and evaluation record ↗</a><a href="/assets/benchmarks/source-snapshots.json">Pinned references and licenses ↗</a></div></section></div>'''
